/* Learning pathways: concept exploration, retrieval practice and guided experiments. */
let learning={mode:'learn',level:'beginner',missions:{},practiceBest:0};try{const stored=JSON.parse(localStorage.getItem('geneed-learning-v2'));if(stored&&typeof stored==='object'){if(['learn','practice','labs'].includes(stored.mode))learning.mode=stored.mode;if(['beginner','familiar','deeper'].includes(stored.level))learning.level=stored.level;if(stored.missions&&typeof stored.missions==='object')learning.missions=stored.missions;if(Number.isFinite(stored.practiceBest))learning.practiceBest=stored.practiceBest}}catch{}
function saveLearning(){try{localStorage.setItem('geneed-learning-v2',JSON.stringify(learning))}catch{}}
const learningTopics=[{title:'DNA & inheritance',tag:'GENETICS',route:'lesson',image:'dna',body:'How does information pass from one generation to the next?',outcome:'Explain base pairing and predict a simple genetic cross.',lab:'inheritance',practice:'quiz'}, {title:'Reading a genome',tag:'GENOMICS',route:'genomics',image:'dna',body:'What can a DNA sequence tell us—and what can’t it tell us?',outcome:'Spot a sequence difference without assuming its biological effect.',lab:'sequence',practice:'practicecheck'}, {title:'Meet the microbial world',tag:'MICROBIOLOGY',route:'microbiology',image:'lab',body:'How are bacteria, viruses and microscopic fungi different?',outcome:'Compare microbes and interpret a simplified growth model.',lab:'growth',practice:'practicecheck'}];
function learningTitle(k,h,p){return `<div class="intro"><div><span class="kicker">${k}</span><h1>${h}</h1><p>${p}</p></div></div>`}
function depth(text){return `<details class="depth" ${learning.level==='deeper'?'open':''}><summary>Go deeper</summary><p>${text}</p></details>`}
function topicCards(mode){return `<div class="cards topic-cards">${learningTopics.map(t=>{const href=mode==='labs'?'lab-'+t.lab:mode==='practice'?t.practice:t.route;return `<article class="card"><div class="card-visual"><img src="assets/${t.image}.jpg" alt="${t.image==='dna'?'Molecular DNA illustration':'Illustrative biology laboratory scene'}" loading="lazy"></div><span class="meta">${t.tag} · FOUNDATIONS</span><h3>${t.title}</h3><p>${t.body}</p><p class="outcome"><strong>You’ll be able to:</strong> ${t.outcome}</p><a href="#${href}">${mode==='learn'?'Explore the concept':mode==='practice'?'Practise your reasoning':'Open the experiment'} →</a></article>`}).join('')}</div>`}
function learningHub(){const count=Object.values(learning.missions).filter(Boolean).length;const next=learning.level==='beginner'&&!progress.lesson?'lesson':!learning.missions.sequence?'genomics':!learning.missions.microbes?'microbiology':!learning.missions.inheritance?'lab-inheritance':!learning.missions.growth?'lab-growth':'practicecheck';return `${learningTitle('GENEED · A SPACE FOR CURIOUS MINDS','Small worlds. Bigger understanding.','Explore genomics and microbiology, at your own pace. No biology background needed.')}<section class="hero hub-hero"><div class="hero-copy"><span class="kicker">FROM CURIOSITY TO UNDERSTANDING</span><h2>Understand the tiny systems<br>that shape life.</h2><p>Start with a question, explore the evidence, then try a challenge. Follow a guided path or choose what interests you.</p><a class="button" href="#${next}">${count?'Continue exploring':'Start with a discovery'} →</a><a class="text-link" href="#learn">Browse all topics</a></div>${helix}</section><section class="path-picker"><div class="section-head"><h2>How do you want to explore?</h2><label class="level-label" for="learning-level">Your starting point<select id="learning-level"><option value="beginner" ${learning.level==='beginner'?'selected':''}>I’m new to biology</option><option value="familiar" ${learning.level==='familiar'?'selected':''}>I know the basics</option><option value="deeper" ${learning.level==='deeper'?'selected':''}>I want more depth</option></select></label></div><div class="mode-tabs" role="tablist" aria-label="Ways to explore">${[['learn','Understand','Clear explanations & hands-on discoveries','lesson'],['practice','Practise','Questions that explain your mistakes','quiz'],['labs','Experiment','Predict, test & interpret a model','simulator']].map(([k,h,p,i])=>`<button role="tab" id="mode-${k}" tabindex="${learning.mode===k?0:-1}" aria-selected="${learning.mode===k}" data-mode="${k}" aria-controls="topic-panel">${icons[i]}<span><strong>${h}</strong><small>${p}</small></span></button>`).join('')}</div><div id="topic-panel" role="tabpanel" aria-labelledby="mode-${learning.mode}" tabindex="0">${topicCards(learning.mode)}</div></section><section class="learning-strip"><div><span class="kicker">YOUR DISCOVERIES</span><h3>${count} of 4 investigations completed</h3><p>Sequence detective · Microbe explorer · Inheritance investigator · Growth investigator</p></div><a href="#glossary">Need a term explained? Open the glossary →</a></section><p class="note">Progress stays on this device. Choose “Go deeper” inside topics for extra context. Current content covers foundations; specialist courses are planned.</p>`}
function learnLibrary(){return `${learningTitle('UNDERSTAND','Follow the questions that interest you.','Each topic combines a short explanation, a worked example and something for you to try.')}<div class="learning-goal"><strong>Learn your way.</strong> Beginners can use the main explanations. If you already know the basics, open the deeper context and move directly to a challenge.</div>${topicCards('learn')}<section class="panel"><h2>How these subjects connect</h2><div class="concept-chain"><div><strong>Genetics</strong><p>Genes, variation and inheritance.</p></div><span>→</span><div><strong>Genomics</strong><p>Whole genomes and patterns across their sequences.</p></div><span>↔</span><div><strong>Microbiology</strong><p>Microbes, their biology and their roles in the world.</p></div></div><p>Microbial genomics connects these fields: researchers can compare microbial DNA to investigate relationships and biological capabilities. Sequence evidence needs biological context.</p></section>`}
let sequenceFound=false,sequenceReasoned=false;
function sequenceActivity(){const ref='ATGCCATGCA',sample='ATGCTATGCA';return `<div class="sequence-box"><div class="section-head"><h3>Sequence detective</h3><span class="pill">Synthetic data · 10 bases</span></div><p>Compare these sequences, both shown in the same 5′ → 3′ direction. Select the position in the sample that differs from the reference.</p><div class="sequence-label">Reference</div><div class="sequence-row">${[...ref].map((b,i)=>`<span><small>${i+1}</small><b>${b}</b></span>`).join('')}</div><div class="sequence-label">Sample · select a base</div><div class="sequence-row">${[...sample].map((b,i)=>`<button data-base="${i}" aria-label="Position ${i+1}: ${b}" class="${sequenceFound&&i===4?'selected-base':''}"><small>${i+1}</small><b>${b}</b></button>`).join('')}</div><div class="feedback" id="sequence-feedback" role="status">${sequenceFound?'Position 5 differs: C in the reference, T in the sample. This is a single-base substitution in this toy sequence.':''}</div>${sequenceFound?`<h3>What can you conclude?</h3><p>Does this change, by itself, show that the sample is harmful?</p><div class="choice-row"><button class="secondary" data-sequence-reason="wrong">Yes, every DNA change is harmful</button><button class="secondary" data-sequence-reason="right">No, more evidence is needed</button></div><div class="feedback" id="sequence-reason" role="status">${sequenceReasoned?'Exactly. A sequence difference is an observation. Its effect depends on location, function and other evidence.':''}</div>`:''}</div>`}
function genomicsLesson(){return `${learningTitle('GENOMICS · GUIDED DISCOVERY','A difference is a clue. Not a conclusion.','Learn to separate what a sequence shows from what you can infer.')}<div class="learning-goal"><strong>By the end:</strong> distinguish a gene from a genome, identify a sequence substitution and explain why a variant’s effect needs context.</div><section class="panel two-col"><div><span class="kicker">THE BIG IDEA</span><h2>From one gene to the whole genome</h2><p>DNA stores information as an ordered sequence of bases. A <strong>gene</strong> is a DNA region that contributes to a functional product. A <strong>genome</strong> is the complete set of genetic material of an organism.</p><p>Genetics often asks how a trait is inherited. Genomics examines the genome more broadly, including regions outside genes and patterns among many genes.</p><div class="feedback"><strong>Think of a library.</strong> A gene is one meaningful passage; the genome is the complete collection. This is a memory aid, not a literal description of how genes work.</div>${depth('Sequencing determines the order of bases. Researchers compare sequences to find variants, but a reference sequence is a comparison framework, not a perfect or “normal” genome. Most genomic comparisons also require quality checks and annotation.')}</div>${helix}</section><section class="panel">${sequenceActivity()}</section><section class="panel"><h2>What happens after finding a difference?</h2><div class="concept-chain"><div><strong>1. Check the observation</strong><p>Could it be a reading or alignment error?</p></div><span>→</span><div><strong>2. Add context</strong><p>Where is it? What is known about that region?</p></div><span>→</span><div><strong>3. Interpret cautiously</strong><p>Use supporting evidence before claiming an effect.</p></div></div><p>These are research reasoning steps. This activity does not analyse personal genomes or interpret health risk.</p><a class="button" href="#practicecheck">Test the distinction →</a></section><p class="note">Read more: <a href="https://www.genome.gov/genetics-glossary/Genomics" target="_blank" rel="noopener">NHGRI · Genomics ↗</a></p>`}
const microbeData={bacteria:{name:'Bacteria',shape:'bacteria',intro:'Single-celled organisms without a membrane-bound nucleus.',dna:'DNA is inside the cell, in a region called the nucleoid; some bacteria also have plasmids.',growth:'Many reproduce by binary fission: one cell divides into two.',role:'Some support ecosystems and food production; some cause disease. “Bacteria” does not mean “harmful”.',deeper:'Bacteria are diverse. Their genomes, structures and metabolism vary. Most textbook drawings show a typical cell; they do not represent every species.'},viruses:{name:'Viruses',shape:'virus',intro:'Non-cellular entities with genetic material inside a protective protein coat; some also have an envelope.',dna:'Their genetic material can be DNA or RNA, depending on the virus.',growth:'They rely on a host cell to make new virus particles.',role:'They affect microbes, plants and animals. They are studied in microbiology even though their status as living entities is debated.',deeper:'A virus is not a very small bacterium. Viruses do not have their own cellular machinery for reproduction.'},fungi:{name:'Microscopic fungi',shape:'fungi',intro:'Eukaryotes: their cells have a nucleus. Yeasts and many moulds are familiar examples.',dna:'Their DNA is organized within a nucleus, with additional DNA in mitochondria.',growth:'Reproduction varies. Many yeasts reproduce by budding; fungi can also form spores.',role:'Yeast helps make bread rise. Fungi also recycle nutrients; some species cause disease.',deeper:'Not every fungus is microscopic. Mushrooms belong to fungi too. Microbiology focuses on the microscopic forms and processes.'}};
let selectedMicrobe='bacteria',microbeAnswered=false;
function microbeDrawing(type){if(type==='bacteria')return `<svg viewBox="0 0 240 170" aria-hidden="true"><rect x="36" y="40" width="168" height="88" rx="44" fill="#dce7ff" stroke="#234db4" stroke-width="4"/><path d="M70 82c20-38 18 38 38 0s18 38 38 0 18 38 28 0M204 82c28 0 0 50 28 50" fill="none" stroke="#d66b59" stroke-width="4"/><g fill="#234db4"><circle cx="68" cy="65" r="4"/><circle cx="165" cy="62" r="4"/><circle cx="95" cy="107" r="4"/><circle cx="151" cy="111" r="4"/></g></svg>`;if(type==='virus')return `<svg viewBox="0 0 240 170" aria-hidden="true"><g stroke="#234db4" stroke-width="4">${Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<path d="M${120+44*Math.cos(a)} ${85+44*Math.sin(a)}L${120+62*Math.cos(a)} ${85+62*Math.sin(a)}"/>`}).join('')}<circle cx="120" cy="85" r="45" fill="#e7eeff"/></g><path d="M104 66c36-15-30 26 14 18s-4 29 24 18" fill="none" stroke="#d66b59" stroke-width="4"/></svg>`;return `<svg viewBox="0 0 240 170" aria-hidden="true"><ellipse cx="114" cy="95" rx="48" ry="54" fill="#fce0d6" stroke="#d66b59" stroke-width="4"/><ellipse cx="168" cy="53" rx="23" ry="28" fill="#fce0d6" stroke="#d66b59" stroke-width="4"/><circle cx="114" cy="96" r="18" fill="#dce7ff" stroke="#234db4" stroke-width="3"/></svg>`}
function microbiologyLesson(){const m=microbeData[selectedMicrobe];return `${learningTitle('MICROBIOLOGY · GUIDED DISCOVERY','A whole world beyond what we can see.','Meet three groups of microbes and learn what makes them different.')}<div class="learning-goal"><strong>By the end:</strong> explain why bacteria and viruses differ, recognize yeast as a fungus, and connect microbial biology with everyday life.</div><section class="panel"><h2>Microbe does not mean germ</h2><p>Microbiology examines microbes and their activities. They help recycle nutrients, support ecosystems and make foods. Some cause disease, but that is only part of their story.</p><p>This first comparison covers bacteria, viruses and microscopic fungi. Archaea, protists and microscopic algae are also important groups; they are outside this first module.</p><div class="lesson-tabs" aria-label="Compare microbes">${Object.entries(microbeData).map(([k,v])=>`<button data-microbe="${k}" aria-pressed="${selectedMicrobe===k}">${v.name}</button>`).join('')}</div><div class="two-col"><div class="microbe-visual">${microbeDrawing(m.shape)}<p class="note">Schematic · not to scale</p></div><div><h2>${m.name}</h2><p>${m.intro}</p><dl class="fact-list"><dt>Genetic material</dt><dd>${m.dna}</dd><dt>How they multiply</dt><dd>${m.growth}</dd><dt>Why they matter</dt><dd>${m.role}</dd></dl>${depth(m.deeper)}</div></div></section><section class="panel"><span class="kicker">APPLY THE IDEA</span><h2>What makes bread dough rise?</h2><p>Baker’s yeast uses sugars and releases carbon dioxide during fermentation. The trapped gas helps dough expand. Which group does yeast belong to?</p><div class="choice-row">${['Bacteria','Viruses','Fungi'].map(x=>`<button class="secondary" data-microbe-answer="${x}">${x}</button>`).join('')}</div><div id="microbe-feedback" class="feedback" role="status">${microbeAnswered?'Correct: fungi. Yeast is a single-celled fungus. Tiny size alone cannot tell you which group a microbe belongs to.':''}</div><div class="actions"><a class="button" href="#lab-growth">Explore growth in a virtual model →</a><a class="text-link" href="#practicecheck">Try a mixed challenge</a></div></section><p class="note">Reference: <a href="https://microbiologysociety.org/why-microbiology-matters/what-is-microbiology.html" target="_blank" rel="noopener">Microbiology Society · What is microbiology? ↗</a></p>`}
const mixedQuestions=[{topic:'Genomics',q:'A genome is best described as…',options:['One gene that controls a trait','The complete set of genetic material of an organism','Only the DNA regions that code for proteins'],correct:1,why:'A genome includes genes and other genetic regions. Genomics asks questions across this wider collection.',review:'genomics'}, {topic:'Genomics',q:'Two sequences differ at one position. What does this observation prove?',options:['The sample causes disease','The sample is a different species','There is a sequence difference; its effect is not yet established'],correct:2,why:'Finding a difference and interpreting its effect are separate tasks. Location, data quality and biological evidence matter.',review:'genomics'}, {topic:'Microbiology',q:'What distinguishes viruses from bacteria?',options:['Viruses are always larger','Viruses need host cells to reproduce; bacteria are cellular organisms','Bacteria have no genetic material'],correct:1,why:'Viruses are non-cellular and depend on host machinery. Bacteria are cells and contain DNA.',review:'microbiology'}, {topic:'Microbiology',q:'Baker’s yeast belongs to which group?',options:['Fungi','Viruses','Bacteria'],correct:0,why:'Yeast is a microscopic fungus with eukaryotic cells. Not all microbes belong to the same group.',review:'microbiology'}, {topic:'Inheritance',q:'For Pp × pp, what fraction of offspring is expected to have white flowers?',options:['0%','25%','50%'],correct:2,why:'The Pp parent contributes P or p with equal probability. The pp parent contributes p. Pp and pp are each expected half the time.',review:'simulator'}, {topic:'Model reasoning',q:'A model predicts eight cells after three doublings, starting with one. Which statement is sound?',options:['Every real microbe grows at that rate','The result follows the assumptions; real conditions can change growth','Viruses divide by binary fission too'],correct:1,why:'The arithmetic is 1 × 2³ = 8. The model assumes all cells divide each generation and ignores limits and cell death.',review:'lab-growth'}];
let mixedIndex=0,mixedAnswers=[],mixedChecked=false;
function practiceLibrary(){return `${learningTitle('PRACTISE','Use what you know. Find what needs another look.','Feedback explains the reasoning and points you to a useful review.')}<div class="two-col"><article class="panel"><span class="kicker">FOCUSED CHECK · 4 QUESTIONS</span><h2>DNA & inheritance</h2><p>Base pairing, alleles, genetic crosses and probability.</p><a class="button" href="#quiz">Start the genetics check →</a></article><article class="panel"><span class="kicker">MIXED CHECK · 6 QUESTIONS</span><h2>Connect the subjects</h2><p>Move between genomics, microbes and model interpretation.</p><a class="button" href="#practicecheck">Start the mixed challenge →</a></article></div><div class="learning-goal">These checks support retrieval practice and conceptual understanding. They are not aligned to a particular exam board or qualification.</div>`}
function mixedPractice(){if(mixedIndex>=mixedQuestions.length){const score=mixedAnswers.filter((x,i)=>x===mixedQuestions[i].correct).length;let review=[...new Set(mixedQuestions.filter((q,i)=>mixedAnswers[i]!==q.correct).map(q=>q.review))];return `${learningTitle('YOUR NEXT STEP','Make the feedback work for you.',`${score} of ${mixedQuestions.length} correct · ${score===6?'Strong connections. Try an experiment next.':'Review the ideas below, then try again.'}`)}<section class="panel"><h2>${review.length?'Suggested review':'Take it further'}</h2><div class="choice-row">${(review.length?review:['labs']).map(r=>`<a class="button" href="#${r}">${({genomics:'Reading a genome',microbiology:'Meet the microbes',simulator:'Genetic crosses','lab-growth':'Growth models',labs:'Virtual experiments'})[r]} →</a>`).join('')}</div>${mixedQuestions.map((q,i)=>`<div class="feedback"><strong>${q.topic}: ${mixedAnswers[i]===q.correct?'Correct':'Revisit this idea'}</strong><p>${q.q}</p>Correct answer: ${q.options[q.correct]}<br>${q.why}</div>`).join('')}<button id="mixed-retry">Try again</button></section>`}const q=mixedQuestions[mixedIndex];return `${learningTitle('MIXED CHALLENGE',q.topic,'Think it through. Feedback follows every answer.')}<section class="panel"><span class="kicker">QUESTION ${mixedIndex+1} OF ${mixedQuestions.length}</span><form id="mixed-form"><fieldset><legend>${q.q}</legend>${q.options.map((o,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" required ${mixedChecked?'disabled':''} ${mixedAnswers[mixedIndex]===i?'checked':''}>${o}</label>`).join('')}</fieldset>${mixedChecked?`<div class="feedback" role="status"><strong>${mixedAnswers[mixedIndex]===q.correct?'Correct.':'Let’s unpack that.'}</strong><br>${q.why}</div><button type="button" id="mixed-next">${mixedIndex===mixedQuestions.length-1?'See review plan':'Next question →'}</button>`:'<button type="submit">Check my reasoning</button>'}</form></section>`}
function virtualLabs(){return `${learningTitle('VIRTUAL EXPERIMENTS','Predict. Test. Explain.','Use simplified models to investigate a question, without needing a physical laboratory.')}<div class="learning-goal"><strong>The aim is reasoning.</strong> These experiments teach interpretation, not physical laboratory procedures or validated experimental skills.</div><div class="cards">${[['inheritance','Why can purple-flowered parents have white-flowered offspring?','Test parent genotypes and explain the recessive outcome.','peas'],['sequence','Does a DNA difference tell the whole story?','Compare a toy sequence and separate observation from interpretation.','dna'],['growth','Can growth continue doubling forever?','Predict a population and explore the assumptions behind a growth model.','lab']].map(([r,h,p,img])=>`<article class="card"><div class="card-visual"><img src="assets/${img}.jpg" alt="${img==='peas'?'Illustrative pea plants':img==='dna'?'Molecular DNA illustration':'Illustrative laboratory scene'}"></div><h3>${h}</h3><p>${p}</p><a href="#lab-${r}">Open investigation →</a></article>`).join('')}</div>`}
let inheritanceRevealed=false,inheritancePrediction='',inheritanceAnswered=false;
function inheritanceLab(){return `${learningTitle('INHERITANCE · GUIDED INVESTIGATION','Two purple parents. One surprising outcome.','A gardener crosses two purple-flowered pea plants. Can white-flowered offspring be possible?')}<div class="two-col"><section class="panel"><span class="kicker">1 · PREDICT</span><h2>Which cross could produce white flowers?</h2><p>For this single-gene model, P gives purple flowers when at least one copy is present. Only pp gives white flowers.</p><fieldset><legend>Choose a hypothesis</legend>${['PP × PP','PP × Pp','Pp × Pp'].map(x=>`<label class="answer"><input type="radio" name="inheritance" value="${x}" ${inheritancePrediction===x?'checked':''}>${x}</label>`).join('')}</fieldset><button id="reveal-inheritance">Test my hypothesis</button><div id="inheritance-feedback" role="status" class="feedback"></div></section><section class="panel"><span class="kicker">2 · EXAMINE THE EVIDENCE</span>${inheritanceRevealed?`<h2>Pp × Pp</h2><div class="offspring-grid">${['PP','Pp','Pp','pp'].map(x=>`<div><strong>${x}</strong><small>${x==='pp'?'White':'Purple'} · 25%</small></div>`).join('')}</div><p>${inheritancePrediction==='Pp × Pp'?'Your hypothesis works.':'Your selected cross cannot produce pp. Here is the cross that can.'} Each parent can contribute P or p. The recessive allele is present even when it is not visible in the parent’s phenotype.</p><h3>3 · Explain the result</h3><p>Why do white flowers appear?</p><div class="choice-row"><button class="secondary" data-inheritance-reason="wrong">The dominant allele disappears</button><button class="secondary" data-inheritance-reason="right">Both parents can pass on p</button></div><div class="feedback" id="inheritance-reason" role="status">${inheritanceAnswered?'Exactly: a pp offspring inherits p from each parent. This is segregation, not blending.':''}</div><a class="text-link" href="#simulator">Explore another parent combination →</a>`:`<h2>Start with a prediction</h2><p>The evidence appears after you choose a hypothesis. It’s fine to be wrong; use the result to revise your explanation.</p>`}</section></div>`}
let growthGenerations=3,growthLimited=false,growthPrediction=null,growthShown=false,growthAnswered=false;
function growthLab(){const unlimited=2**growthGenerations,modeled=growthLimited?Math.min(16,unlimited):unlimited;return `${learningTitle('MICROBIOLOGY · MODEL INVESTIGATION','When does “doubling” stop being a useful model?','Explore generations of cell division with a deliberately simplified population model.')}<div class="learning-goal">Start with <strong>one cell</strong>. One generation means every modeled cell divides once. No species or real-world growth time is implied.</div><div class="two-col"><section class="panel"><span class="kicker">1 · SET UP & PREDICT</span><label for="generations">Number of generations</label><select id="generations">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${growthGenerations===n?'selected':''}>${n} generations</option>`).join('')}</select><label class="answer"><input id="growth-limit" type="checkbox" ${growthLimited?'checked':''}>Add a toy resource cap of 16 cells</label><label for="growth-prediction">Your predicted population</label><input class="number-input" id="growth-prediction" type="number" min="1" max="100000" step="1" value="${growthPrediction??''}"><button id="run-growth">Run the model →</button><p class="note">Unlimited model: N = 1 × 2ⁿ. Limited model: min(16, 2ⁿ). The abrupt cap is a teaching device, not a biological growth law.</p><div class="feedback" id="growth-feedback" role="status"></div></section><section class="panel"><span class="kicker">2 · INTERPRET</span>${growthShown?`<h2>${modeled} modeled cells</h2><div class="growth-chart" role="img" aria-label="Population across ${growthGenerations} generations, ending at ${modeled} cells">${Array.from({length:growthGenerations+1},(_,i)=>{let n=growthLimited?Math.min(16,2**i):2**i;return `<div><b>${n}</b><span style="height:${20+n/Math.max(16,modeled)*110}px"></span><small>G${i}</small></div>`}).join('')}</div><p>${growthPrediction===modeled?'Your prediction matches the model.':`You predicted ${growthPrediction}; the model gives ${modeled}.`} ${growthLimited?'The cap stops the modeled increase at 16.':'Each generation multiplies the previous population by two.'}</p><h3>3 · Check the limitation</h3><p>Why might real growth depart from this pattern?</p><div class="choice-row"><button class="secondary" data-growth-reason="right">Resources, conditions and cell death can change growth</button><button class="secondary" data-growth-reason="wrong">All microbes must double forever</button></div><div class="feedback" id="growth-reason" role="status">${growthAnswered?'Correct. This model makes assumptions. Real growth depends on the organism and environment; a curve alone does not identify a microbe.':''}</div>`:`<h2>Your prediction comes first</h2><p>After you run the model, compare prediction and result. Then turn the resource cap on or off to see why assumptions matter.</p>`}</section></div>`}
function glossary(){const terms=[['DNA','A molecule that stores genetic information as a sequence of bases.'],['Gene','A region of DNA that contributes to a functional product, such as a protein or RNA.'],['Genome','An organism’s complete set of genetic material.'],['Allele','A version of DNA at a particular genomic location.'],['Genotype','The genetic makeup at the location or locations being considered; Pp is an example.'],['Phenotype','An observable characteristic; purple flower color is an example.'],['Heterozygous','Two different alleles at a locus in a diploid model.'],['Homozygous','Two identical alleles at a locus in a diploid model.'],['Variant','A difference in a DNA sequence relative to a comparison sequence.'],['Prokaryote','An organism whose cells lack a membrane-bound nucleus; bacteria and archaea are prokaryotes.'],['Eukaryote','An organism whose cells have a nucleus; fungi are eukaryotes.'],['Binary fission','A cell-division process in which one cell produces two daughter cells.'],['Host','An organism or cell that another biological entity depends on or lives in.']];return `${learningTitle('PLAIN-LANGUAGE GLOSSARY','A term should open a door.','Quick definitions for the concepts used in the current modules.')}<section class="panel"><label for="glossary-search">Find a term</label><input class="number-input" id="glossary-search" type="search" placeholder="Try genome, allele or host"><dl class="glossary">${terms.map(([t,d])=>`<div data-glossary="${t.toLowerCase()} ${d.toLowerCase()}"><dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl><p id="glossary-empty" hidden>No matching term. Try a shorter word.</p></section>`}
function bindLearning(){document.querySelectorAll('[data-mode]').forEach((b,i)=>b.onkeydown=e=>{const buttons=[...document.querySelectorAll('[data-mode]')];let target;if(e.key==='ArrowRight')target=(i+1)%buttons.length;if(e.key==='ArrowLeft')target=(i+buttons.length-1)%buttons.length;if(e.key==='Home')target=0;if(e.key==='End')target=buttons.length-1;if(target!==undefined){e.preventDefault();buttons[target].click()}});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{learning.mode=b.dataset.mode;saveLearning();render();document.querySelector(`[data-mode="${learning.mode}"]`).focus()});if(document.querySelector('#learning-level'))document.querySelector('#learning-level').onchange=e=>{learning.level=e.target.value;saveLearning();render();document.querySelector('#learning-level').focus()};document.querySelectorAll('[data-base]').forEach(b=>b.onclick=()=>{if(+b.dataset.base===4){sequenceFound=true;render();document.querySelector('#sequence-feedback').focus()}else document.querySelector('#sequence-feedback').textContent=`Position ${+b.dataset.base+1} matches. Compare the bases again, one column at a time.`});document.querySelectorAll('[data-sequence-reason]').forEach(b=>b.onclick=()=>{if(b.dataset.sequenceReason==='right'){sequenceReasoned=true;learning.missions.sequence=true;saveLearning()}document.querySelector('#sequence-reason').textContent=b.dataset.sequenceReason==='right'?'Exactly. The effect needs context and supporting evidence. Sequence investigation completed.':'Not every difference is harmful. Consider where it occurs and what evidence supports an effect.'});document.querySelectorAll('[data-microbe]').forEach(b=>b.onclick=()=>{selectedMicrobe=b.dataset.microbe;render();document.querySelector(`[data-microbe="${selectedMicrobe}"]`).focus()});document.querySelectorAll('[data-microbe-answer]').forEach(b=>b.onclick=()=>{const right=b.dataset.microbeAnswer==='Fungi';if(right){microbeAnswered=true;learning.missions.microbes=true;saveLearning()}document.querySelector('#microbe-feedback').textContent=right?'Correct: fungi. Yeast is a single-celled fungus. Microbe investigation completed.':'Yeast has a nucleus and belongs to fungi. Tiny size alone does not define the group.'});if(document.querySelector('#mixed-form'))document.querySelector('#mixed-form').onsubmit=e=>{e.preventDefault();const a=new FormData(e.target).get('answer');if(a===null)return;mixedAnswers[mixedIndex]=+a;mixedChecked=true;render();document.querySelector('#mixed-next').focus()};if(document.querySelector('#mixed-next'))document.querySelector('#mixed-next').onclick=()=>{mixedIndex++;mixedChecked=false;if(mixedIndex===mixedQuestions.length){learning.practiceBest=Math.max(learning.practiceBest,mixedAnswers.filter((x,i)=>x===mixedQuestions[i].correct).length);saveLearning()}render();main.focus()};if(document.querySelector('#mixed-retry'))document.querySelector('#mixed-retry').onclick=()=>{mixedIndex=0;mixedAnswers=[];mixedChecked=false;render()};if(document.querySelector('#reveal-inheritance'))document.querySelector('#reveal-inheritance').onclick=()=>{const a=document.querySelector('input[name=inheritance]:checked');if(!a){document.querySelector('#inheritance-feedback').textContent='Choose a hypothesis first.';return}inheritancePrediction=a.value;inheritanceRevealed=true;render()};document.querySelectorAll('[data-inheritance-reason]').forEach(b=>b.onclick=()=>{inheritanceAnswered=b.dataset.inheritanceReason==='right';if(inheritanceAnswered){learning.missions.inheritance=true;saveLearning()}document.querySelector('#inheritance-reason').textContent=inheritanceAnswered?'Exactly. Each heterozygous parent can contribute p, allowing pp offspring.':'P has not disappeared. The pp combination contains a recessive allele from each parent.'});if(document.querySelector('#generations'))document.querySelector('#generations').onchange=e=>{growthGenerations=+e.target.value;growthShown=false;render()};if(document.querySelector('#growth-limit'))document.querySelector('#growth-limit').onchange=e=>{growthLimited=e.target.checked;growthShown=false;render()};if(document.querySelector('#run-growth'))document.querySelector('#run-growth').onclick=()=>{const input=document.querySelector('#growth-prediction');if(!input.value||!input.checkValidity()){document.querySelector('#growth-feedback').textContent='Enter a whole-number prediction of at least one cell.';input.focus();return}growthPrediction=+input.value;growthShown=true;render()};document.querySelectorAll('[data-growth-reason]').forEach(b=>b.onclick=()=>{growthAnswered=b.dataset.growthReason==='right';if(growthAnswered){learning.missions.growth=true;saveLearning()}document.querySelector('#growth-reason').textContent=growthAnswered?'Correct. Conditions, resources and cell death matter. Growth investigation completed.':'Growth is not unlimited in real environments. Think about resources and changing conditions.'});if(document.querySelector('#glossary-search'))document.querySelector('#glossary-search').oninput=e=>{const q=e.target.value.toLowerCase().trim();let visible=0;document.querySelectorAll('[data-glossary]').forEach(x=>{x.hidden=!x.dataset.glossary.includes(q);if(!x.hidden)visible++});document.querySelector('#glossary-empty').hidden=visible>0}}
